use semio_framework_test_fixtures::fixture_text;
use semio_framework_value::{RetirementDemand,RetainedCloneGrant,retained_utf8::{RetainedUtf8Cursor,RetainedUtf8Buffer}};
use semio_framework_value_testing_allocator as _;
#[test]
fn original_utf8_byte_validation_matches_independent_decoder_across_boundaries(){
 let fixture:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔤️bytes.json")).unwrap();for row in fixture["cases"].as_array().unwrap(){let bytes:Vec<u8>=row["bytes"].as_array().unwrap().iter().map(|v|v.as_u64().unwrap()as u8).collect();let expected=row["valid"].as_bool().unwrap();assert_eq!(encoding_rs::UTF_8.decode_without_bom_handling_and_without_replacement(&bytes).is_some(),expected);for page in 1..=4{let mut cursor=semio_framework_value::retained_utf8::RetainedUtf8BytesCursor::new();let mut valid=true;for _ in 0..128{let mut g=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:semio_framework_value::retained_utf8::RetainedUtf8BytesCursor::fixed_copy_bytes()+page,maximum_capacity_bytes:0,maximum_release_bytes:0,maximum_depth:1};let before=cursor;g.maximum_items=0;let denied=cursor.advance(&bytes,g,1);assert!(denied.result.is_ok());assert_eq!(cursor,before);g.maximum_items=1;let turn=cursor.advance(&bytes,g,page as u64);match turn.result{Ok(step)=>{assert!(step.progress.fits(g));if step.complete{break}},Err(_)=>{valid=false;break}}}assert_eq!(valid&&cursor.complete(),expected,"page {page}: {bytes:?}");}}
}
#[test]
fn original_utf8_byte_validation_keeps_source_and_reports_inspected_work(){
 let bytes=vec![0xe2,0x82,0xac,b'x'];let other=bytes.clone();let mut cursor=semio_framework_value::retained_utf8::RetainedUtf8BytesCursor::new();let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:semio_framework_value::retained_utf8::RetainedUtf8BytesCursor::fixed_copy_bytes()+2,maximum_capacity_bytes:0,maximum_release_bytes:0,maximum_depth:1};let first=cursor.advance(&bytes,grant,1);assert_eq!(first.work,1);assert!(!first.result.unwrap().complete);let saved=cursor;let wrong=cursor.advance(&other,grant,1);assert!(wrong.result.is_err());assert_eq!(wrong.work,0);assert_eq!(cursor,saved);let no_fuel=cursor.advance(&bytes,grant,0);assert_eq!(no_fuel.work,0);assert_eq!(cursor,saved);let second=cursor.advance(&bytes,grant,2);assert_eq!(second.work,2);assert!(!second.result.unwrap().complete);let last=cursor.advance(&bytes,grant,1);assert_eq!(last.work,1);assert!(last.result.unwrap().complete);assert_eq!(bytes,vec![0xe2,0x82,0xac,b'x']);
}
fn grant(d:RetirementDemand)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes.max(257),maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth}}
fn close(writer:&mut RetainedUtf8Buffer)->(usize,usize){writer.begin_close();let maximum_turns=64usize.saturating_add(writer.capacity().saturating_mul(4));let(mut born,mut released,mut turns,mut work)=(0,0,0,0u64);while !writer.terminal_is_empty(){let d=writer.close_demand(257).unwrap();let(short,heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||writer.close_step(RetainedCloneGrant{maximum_items:0,..grant(d)}));assert_eq!(short.work,0);assert_eq!(short.result.unwrap().progress(),Default::default());assert_eq!(heap,(0,0));let(turn,heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||writer.close_step(grant(d)));work+=turn.work;let step=turn.result.unwrap();assert_eq!(heap,(step.progress().retained_capacity_bytes,step.progress().released_bytes));assert!(step.progress().fits(grant(d)));born+=heap.0;released+=heap.1;turns+=1;assert!(turns<maximum_turns);}let(turn,heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||writer.close_step(Default::default()));assert_eq!(turn.work,0);assert_eq!(heap,(0,0));assert_eq!(turn.result.unwrap().progress(),Default::default());if released>0{assert!(work>0)}(born,released)}

#[test]
fn original_utf8_cursor_pages_match_portable_scalar_offsets_without_allocations(){
 let fixture:serde_json::Value=serde_json::from_str(fixture_text!("../../📝️text/🚶️utf8/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();for row in fixture["cases"].as_array().unwrap(){let text=row["text"].as_str().unwrap().repeat(row["repeat"].as_u64().unwrap()as usize);let pointer=text.as_ptr();let mut cursor=RetainedUtf8Cursor::new();while !cursor.ready(){let before=cursor;let d=cursor.demand(&text).unwrap();let(refused,heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||cursor.advance(&text,RetainedCloneGrant{maximum_copy_bytes:d.copy_bytes-1,..grant(d)}).unwrap());assert_eq!(refused.progress,Default::default());assert_eq!(heap,(0,0));assert_eq!(cursor,before);let(step,heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||cursor.advance(&text,grant(d)).unwrap());assert_eq!(heap,(0,0));assert!(step.progress.fits(grant(d)));assert!(text.is_char_boundary(step.start_byte)&&text.is_char_boundary(step.end_byte));assert_eq!(step.end_scalar-step.start_scalar,text[step.start_byte..step.end_byte].chars().count());}assert_eq!(cursor.byte_offset(),row["bytes"].as_u64().unwrap()as usize);assert_eq!(cursor.scalar_offset(),row["scalars"].as_u64().unwrap()as usize);assert_eq!(text.as_ptr(),pointer);}
}

#[test]
fn original_utf8_buffer_funds_transfer_and_every_cancellation_frontier(){
 let fixture:serde_json::Value=serde_json::from_str(fixture_text!("../../📝️text/🚶️utf8/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();for row in fixture["cases"].as_array().unwrap(){let source=row["text"].as_str().unwrap().repeat(row["repeat"].as_u64().unwrap()as usize);let pointer=source.as_ptr();let cuts=fixture["cancellationCuts"].as_array().unwrap().iter().map(|cut|Some(cut.as_u64().unwrap()as usize)).chain(std::iter::once(None));for cut in cuts{let(mut writer,heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||RetainedUtf8Buffer::new(source.len()));assert_eq!(heap,(0,0));let d=writer.reserve_demand();let(short,heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||writer.reserve(RetainedCloneGrant{maximum_items:0,..grant(d)}).unwrap());assert_eq!(heap,(0,0));assert_eq!(short,Default::default());let(born,heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||writer.reserve(grant(d)).unwrap());assert_eq!(heap,(born.retained_capacity_bytes,0));let(mut offset,mut turns)=(0,0);while offset<source.len()&&cut.is_none_or(|cut|turns<cut){let d=writer.append_demand(&source,offset).unwrap();let(step,heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||writer.append(&source,offset,grant(d)).unwrap());assert_eq!(heap,(0,0));assert!(step.progress.fits(grant(d)));assert!(step.end_byte>offset);offset=step.end_byte;turns+=1;}if cut.is_none(){let d=writer.take_demand().unwrap();let(output,heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||writer.take(grant(d)).unwrap().unwrap());assert_eq!(heap,(0,0));assert_eq!(output.0,source);assert!(output.1.fits(grant(d)));assert_eq!(close(&mut writer),(0,0));drop(output);}else{let(close_birth,released)=close(&mut writer);assert_eq!(released,born.retained_capacity_bytes+close_birth);}assert_eq!(source.as_ptr(),pointer);}}
}
